CREATE TEMPORARY VIEW all_new_item_${grass_region_without_quote} AS
select
     item_id
from srdi_mart.dim_sr_data_warehouse_item
where grass_region in (${grass_region}) and local_date = ${local_date}
and datediff(${local_date}, from_unixtime(item_create_timestamp, 'yyyy-MM-dd')) < 90
;
--sql_divide_splitter--

create temporary view all_cspu_link_${grass_region_without_quote} as
SELECT
     cspu_id
    ,item_id
FROM srdi_mart.dwd_sr_data_warehouse_cspu_model_all_link_hf
where grass_region in (${grass_region}) and regional_date = ${local_date}
group by 1,2
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW item_data_${grass_region_without_quote} AS
select
     item_id
    ,imp_cnt
    ,click_cnt
    ,order_cnt
from srdi_mart.dws_sr_data_warehouse_ni_boost_offline_common_1d
WHERE grass_region IN (${grass_region}) AND regional_date = ${local_date}
and exp_tag ='C1'
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW cspu_data_${grass_region_without_quote} AS
SELECT
     cspu_id
    ,coalesce(sum(imp_cnt),0)   as imp_cnt -- 加上coalesce，保证结果可以代表：如果imp不为null，就是被cspu覆盖的含义
    ,coalesce(sum(click_cnt),0) as click_cnt
    ,coalesce(sum(order_cnt),0) as order_cnt
FROM all_cspu_link_${grass_region_without_quote} a
left join item_data_${grass_region_without_quote} b on a.item_id=b.item_id
group by cspu_id
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_ni_boost_item_cspu_1d PARTITION (grass_region = ${grass_region}, regional_date = ${local_date})
SELECT
     c.item_id
    ,sum(imp_cnt)   as cspu_imp_cnt
    ,sum(click_cnt) as cspu_click_cnt
    ,sum(order_cnt) as cspu_order_cnt
from(-- 只要至少被一个cspu覆盖的itemid
    select
        a.item_id
       ,b.cspu_id
    FROM all_new_item_${grass_region_without_quote} a
    inner join all_cspu_link_${grass_region_without_quote} b on a.item_id=b.item_id
) c
left join cspu_data_${grass_region_without_quote} d on c.cspu_id=d.cspu_id
group by c.item_id
;
